Object.assign(window.DYLEAN_DATA.files["Library/Init/Control/Id.lean"],{"text":"/-\nCopyright (c) 2017 Microsoft Corporation. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Sebastian Ullrich\n\nThe identity Monad.\n-/\nmodule\n\nprelude\npublic import Init.Control.MonadAttach\n\npublic section\n\nuniverse u\n\n/--\nThe identity function on types, used primarily for its `Monad` instance.\n\nThe identity monad is useful together with monad transformers to construct monads for particular\npurposes. Additionally, it can be used with `do`-notation in order to use control structures such as\nlocal mutability, `for`-loops, and early returns in code that does not otherwise use monads.\n\nExamples:\n```lean example\ndef containsFive (xs : List Nat) : Bool := Id.run do\n  for x in xs do\n    if x == 5 then return true\n  return false\n```\n\n```lean example\n#eval containsFive [1, 3, 5, 7]\n```\n```output\ntrue\n```\n-/\n@[expose, implicit_reducible] def Id (type : Type u) : Type u := type\n\nnamespace Id\n\n@[always_inline]\ninstance : Monad Id where\n  pure x := x\n  bind x f := f x\n  map f x := f x\n\n/--\nThe identity monad has a `bind` operator.\n-/\n@[instance_reducible]\ndef hasBind : Bind Id :=\n  inferInstance\n\n/--\nRuns a computation in the identity monad.\n\nThis function is the identity function. Because its parameter has type `Id α`, it causes\n`do`-notation in its arguments to use the `Monad Id` instance.\n-/\n@[always_inline, inline, expose, implicit_reducible]\nprotected def run (x : Id α) : α := x\n\ninstance [OfNat α n] : OfNat (Id α) n :=\n  inferInstanceAs (OfNat α n)\n\ninstance {m : Type u → Type v} [Pure m] : MonadLiftT Id m where\n  monadLift x := pure x.run\n\ninstance : MonadAttach Id where\n  CanReturn x a := x.run = a\n  attach x := pure ⟨x.run, rfl⟩\n\ninstance : LawfulMonadAttach Id where\n  map_attach := rfl\n  canReturn_map_imp := by\n    intro _ _ x _ h\n    cases h\n    exact x.run.2\n\nend Id\n\n/-- Turn a collection with a pure `ForIn` instance into an array. -/\n@[expose] def ForIn.toArray {α : Type u} [inst : ForIn Id ρ α] (xs : ρ) : Array α :=\n  ForIn.forIn xs Array.empty (fun a acc => pure (.yield (acc.push a))) |> Id.run\n\n/-- Turn a collection with a pure `ForIn` instance into a list. -/\n@[expose] def ForIn.toList {α : Type u} [ForIn Id ρ α] (xs : ρ) : List α :=\n  ForIn.toArray xs |>.toList\n","refs":[[38,34,38,36,"cea75ed83e30",true],[43,11,43,16,"0cabd2e0ecff",false],[43,17,43,19,"cea75ed83e30",false],[44,2,44,6,"cd6ca40bdb4e",false],[45,2,45,6,"b92ad1745a09",false],[52,19,52,21,"cea75ed83e30",false],[53,2,53,15,"8f3d9a99bb5b",false],[62,14,62,17,"449a66687de9",true],[62,23,62,25,"cea75ed83e30",false],[64,30,64,32,"cea75ed83e30",false],[67,53,67,55,"cea75ed83e30",false],[68,2,68,11,"cd68667648a8",false],[68,17,68,21,"cd6ca40bdb4e",false],[68,24,68,27,"449a66687de9",false],[70,23,70,25,"cea75ed83e30",false],[71,21,71,24,"449a66687de9",false],[72,14,72,18,"cd6ca40bdb4e",false],[72,22,72,25,"449a66687de9",false],[72,27,72,30,"4678ade8cd63",false],[74,29,74,31,"cea75ed83e30",false],[75,16,75,19,"4678ade8cd63",false],[79,12,79,15,"449a66687de9",false],[79,16,79,17,"2cae3caad7d8",false],[84,55,84,57,"cea75ed83e30",false],[84,74,84,79,"b78edb964ebc",false],[85,2,85,13,"e5a26fce8d44",false],[85,43,85,47,"cd6ca40bdb4e",false],[85,49,85,55,"fbc0415d3e63",false],[85,61,85,65,"df0c0e9ca0f0",false],[85,74,85,80,"449a66687de9",false],[88,47,88,49,"cea75ed83e30",false],[88,66,88,70,"c81e4058f78f",false],[89,22,89,28,"795dd38987f6",false]]});
